ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
"wsConsultaSAAWResponse": {
  "wsResponseHeader": {
    "system": {
      "name": vars.name, 
      "correlationId": vars.correlationId, 
      "processingServer": vars.source
    },
    "service": {
      "status": "PASS", 
      "responseDate": vars.dateTime 
    }
  },
  "saawQueryResponse": {
    "result": {
      "contractAccount": payload.saawQueryResponse.result.contractAccount, 
      "error": payload.saawQueryResponse.result.error, 
      "claimStatus": payload.saawQueryResponse.result.claimStatus, 
      "claimDate": payload.saawQueryResponse.result.claimDate, 
      "customerIdentification": payload.saawQueryResponse.result.customerIdentification, 
      "customerName": payload.saawQueryResponse.result.customerName, 
      "claimantName": payload.saawQueryResponse.result.claimantName, 
      "cunNumber": payload.saawQueryResponse.result.cunNumber, 
      "customerSegment": payload.saawQueryResponse.result.customerSegment,
      "claimValue": payload.saawQueryResponse.result.claimValue
      }
    }
  }
}
